/* local-mvp-0.4: same-origin development service client. No credentials or private data in localStorage. */
const generationClient={user:null,csrfToken:null,health:null,curriculum:null,profile:null,jobs:[],chapters:[],submissions:[],reviews:[],detail:null,chapter:null,epoch:0,timer:null,controller:null,active:false,busy:false,message:'',authMode:'login',selectedJob:'',selectedChapter:'',drafts:{},dirty:false};
const generationStatus={queued:'排队中',running:'运行中',succeeded:'草稿已保存',failed:'失败',cancelled:'已取消'};
const generationMissingLabel=value=>/API_KEY|generation_service|readiness_interface/.test(value)?'模型服务尚未配置':/MODEL/.test(value)?'模型选择尚未配置':/BUDGET|COST|budget/i.test(value)?'调用额度或预算尚未配置':/OUTPUT|INPUT|Chars/.test(value)?'生成长度限制尚未配置':/TIMEOUT/.test(value)?'调用超时限制尚未配置':'生成服务尚未就绪';
const generationStage={sources_validating:'资料检查',generating:'模型调用',structure_validating:'结构检查',draft_ready:'草稿待保存'};
const generationEscape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const generationText=v=>typeof v==='string'?v:JSON.stringify(v??'',null,2);
function generationAllowedSource(url){try{const u=new URL(url);return u.protocol==='https:'&&!u.username&&!u.password&&['genai.owasp.org','cheatsheetseries.owasp.org'].includes(u.hostname)&&!(u.port&&u.port!=='443')?u.href:null;}catch{return null;}}
function generationSourceHTML(s){const url=generationAllowedSource(s.url);return `<article class="generation-source"><h4>${url?`<a href="${generationEscape(url)}" target="_blank" rel="noopener noreferrer">${generationEscape(s.title||s.id)}</a>`:generationEscape(s.title||s.id)}</h4><p>${generationEscape(s.id)} · 版本 ${generationEscape(s.version||'未知')} · 访问 ${generationEscape(s.accessedAt||'未知')}</p><p>位置：${generationEscape(generationText(s.verifiedSections||s.locator||'未知'))}</p><blockquote>${generationEscape(s.excerpt||'未提供片段')}</blockquote><p>${generationEscape(s.limits||'来源链接不证明新稿内容正确')}</p></article>`;}
// Deliberately plain, escaped Markdown: no HTML/link execution from model or user content.
function generationMarkdown(text){return `<div class="generation-markdown">${generationEscape(generationText(text))}</div>`;}
function generationAuthorHTML(){const c=typeof generationCurriculumData==='undefined'?null:generationCurriculumData;if(!c)return '<p>作者初稿资源未加载。</p>';return `<details class="card generation-author"><summary>独立阅读作者初稿 · e03 ${generationEscape(c.title)}</summary><p>来源：教材研发员 · ${generationEscape(c.review?.author?.version||'未知')}；课程接收：结构初稿可接收，非专业审核。伪代码与预期结果均未运行，CR05运行缺证开放；学习效果未验证。</p><p>先修：${generationEscape((c.prerequisites||[]).join('、'))}。本稿不是模型生成结果。</p>${(c.sections||[]).map((s,i)=>`<section><h3>${i+1}. ${generationEscape(s.title)}</h3>${generationMarkdown(s.bodyMarkdown)}<p class="note">作者版本 ${generationEscape(s.originVersion)} · 执行状态：未运行 · 原文 SHA256 ${generationEscape(s.bodySha256)}</p></section>`).join('')}<h3>受控来源与位置</h3>${(c.allowedSources||[]).map(generationSourceHTML).join('')}</details>`;}
function generationPage(){return `<div class="page-title"><div><span class="eyebrow">LOCAL DEVELOPMENT · local-mvp-0.4</span><h1>单章生成与作品复盘</h1><p>本地研发服务 · 完整产品未达标。真实任务、教材草稿、作品自述与审核状态分别保存。</p></div></div><div class="info-banner">原静态学习记录继续保留；新研发账户由服务识别，需要重新选择学习起点。file 与 HTTP 的旧浏览器存储可能不同，不自动迁移。</div><div id="generation-feedback" role="status" aria-live="polite"></div><section id="generation-connection" class="card"></section><section id="generation-account" class="card section-gap"></section><div id="generation-private" hidden><section id="generation-profile" class="card section-gap"></section><section class="card section-gap"><h2>2. 请求受控 e03 草稿</h2><div id="generation-config"></div><button class="primary" data-generation="generate" id="generation-submit" disabled>请求生成 e03 草稿</button><p>成功只代表真实草稿已保存；内容正确、示例执行与专业审核仍需独立证据。不会回退固定教材冒充生成。</p><div id="generation-jobs"></div><div id="generation-detail"></div></section><section class="card section-gap"><h2>3. 我的模型草稿版本</h2><div id="generation-chapters"></div><div id="generation-chapter"></div></section><section id="generation-submission" class="card section-gap"></section><section id="generation-review" class="card section-gap"></section><section id="generation-history" class="card section-gap"></section></div>${generationAuthorHTML()}`;}
function generationHasDraft(){return generationClient.dirty;}
function generationCanLeave(){return !generationHasDraft()||typeof window.confirm!=='function'||window.confirm('本地服务表单尚未提交；当前页面内存保留输入，刷新会丢失。确定离开？');}
function generationUserError(error){const message=String(error?.message||'请求失败');if(/config_missing|budget_missing|budget_exceeded/.test(message))return '真实生成已阻止：模型服务、模型选择或调用额度尚未就绪，请由研发人员检查配置。';return message;}
function generationNotify(message,error=false){generationClient.message=message;const el=document.getElementById('generation-feedback');if(el){el.textContent=message;el.setAttribute('role',error?'alert':'status');}}
function generationClearPrivate(){const g=generationClient;g.epoch++;g.controller?.abort();g.controller=null;clearTimeout(g.timer);g.timer=null;Object.assign(g,{user:null,csrfToken:null,profile:null,jobs:[],chapters:[],submissions:[],reviews:[],detail:null,chapter:null,selectedJob:'',selectedChapter:'',drafts:{},dirty:false,busy:false});}
async function generationApi(path,method='GET',body,epoch=generationClient.epoch){if(!/^\/api\/(health|curriculum|auth\/(register|login|me|logout)|profile|generation-jobs(?:\/[a-zA-Z0-9-]+(?:\/(cancel|retry))?)?|chapters(?:\/[a-zA-Z0-9-]+)?|submissions|reviews|export)$/.test(path))throw new Error('拒绝非受控接口');if(!['http:','https:'].includes(location.protocol))throw new Error('当前静态页面没有同源本地服务');const headers={Accept:'application/json'};if(body!==undefined)headers['Content-Type']='application/json';if(method!=='GET'&&generationClient.csrfToken)headers['X-CSRF-Token']=generationClient.csrfToken;const response=await fetch(path,{method,headers,body:body===undefined?undefined:JSON.stringify(body),credentials:'same-origin',cache:'no-store',signal:generationClient.controller?.signal});let data;try{data=await response.json();}catch{throw new Error('服务未返回有效JSON；请确认使用本地研发服务启动命令');}if(epoch!==generationClient.epoch)throw new Error('账户已变化，旧响应已丢弃');if(!response.ok){if(response.status===401&&generationClient.user){generationClearPrivate();generationRenderAccount();generationNotify('研发会话已失效，请重新登录。未提交私有输入已清空。',true);}const err=new Error(`${data.error?.code||response.status}：${data.error?.message||'服务请求失败'}`);err.status=response.status;throw err;}return data;}
function generationUnmount(){const g=generationClient;g.active=false;clearTimeout(g.timer);g.timer=null;g.controller?.abort();g.controller=null;}
async function generationMount(){const g=generationClient;g.active=true;g.controller=new AbortController();document.getElementById('generation-feedback').textContent=g.message;generationRenderAccount();if(location.protocol==='file:'){document.getElementById('generation-connection').innerHTML='<h2>当前为静态页面</h2><p>单章生成需要本地服务。此页面只读作者初稿，不发出真实生成请求。</p><pre><code>cd sites/rolecraft\nnode ../../scripts/start-local.mjs</code></pre><p>在已启动的服务地址打开网站；实际地址以终端输出为准。供应商密钥只能通过服务端环境配置。</p>';return;}document.getElementById('generation-connection').innerHTML='<h2>正在连接同源本地服务</h2><button class="outline" data-generation="reconnect">重新连接</button>';try{const epoch=g.epoch;const [health,curriculum]=await Promise.all([generationApi('/api/health','GET',undefined,epoch),generationApi('/api/curriculum','GET',undefined,epoch)]);if(!g.active||epoch!==g.epoch)return;g.health=health;g.curriculum=curriculum;document.getElementById('generation-connection').innerHTML=`<h2>本地研发服务已连接</h2><p>${generationEscape(health.productVersion)} · ${generationEscape(health.mode)}。本机研发账户不是生产认证。</p><button class="outline" data-generation="reconnect">重新连接／刷新配置</button>`;const identity=await generationApi('/api/auth/me','GET',undefined,epoch).catch(e=>{if(e.status===401)return null;throw e;});if(!g.active||epoch!==g.epoch)return;if(identity){g.user=identity.user;g.csrfToken=identity.csrfToken;}else generationClearPrivate();generationRenderAccount();if(g.user){await generationRefresh(true);generationPoll();}}catch(e){if(e.name==='AbortError')return;g.health=null;generationRenderStatus();generationNotify(generationUserError(e),true);const el=document.getElementById('generation-connection');if(el)el.innerHTML='<h2>本地服务不可达或协议不匹配</h2><p>这属于连接错误，不能推断供应商已配置。请检查启动终端。</p><button class="outline" data-generation="reconnect">重新连接</button>';}}
function generationRenderAccount(){const g=generationClient,el=document.getElementById('generation-account');if(!el)return;const available=['http:','https:'].includes(location.protocol);document.getElementById('generation-private').hidden=!g.user;if(g.user){el.innerHTML=`<h2>本地研发身份</h2><p>${generationEscape(g.user.email)}</p><div class="action-row"><button class="outline" data-generation="logout">退出研发账户</button><button class="outline" data-generation="export">导出当前账户数据</button></div><p>任务、版本和自评按服务端账户隔离，退出会清除当前界面私有缓存及未提交输入。</p>`;return;}el.innerHTML=`<h2>${g.authMode==='register'?'创建':'登录'}本地研发账户</h2><form id="generation-auth-form" class="generation-form"><label for="generation-email">邮箱</label><input id="generation-email" name="email" type="email" required autocomplete="username" ${available?'':'disabled'}><label for="generation-password">密码（12—128位）</label><input id="generation-password" name="password" type="password" minlength="12" maxlength="128" required autocomplete="${g.authMode==='register'?'new-password':'current-password'}" ${available?'':'disabled'}><div class="action-row"><button class="primary" type="submit" ${available?'':'disabled'}>${g.authMode==='register'?'创建本地研发账户':'登录研发账户'}</button><button class="outline" type="button" data-generation="auth-switch">${g.authMode==='register'?'已有账户，登录':'创建新研发账户'}</button></div></form><p>仅用于本机研发，不能作为生产身份认证。密码、会话与新账户私有记录不会写入浏览器localStorage。</p>`;}
function generationField(name,label,value='',required=false,type='textarea'){const id='generation-'+name;return `<label for="${id}">${generationEscape(label)}</label>${type==='input'?`<input id="${id}" name="${name}" maxlength="2000" value="${generationEscape(value)}" ${required?'required':''}>`:`<textarea id="${id}" name="${name}" maxlength="${name==='goal'?2000:10000}" ${required?'required':''}>${generationEscape(value)}</textarea>`}`;}
function generationRenderForms(){const g=generationClient;if(!g.user)return;const p=g.drafts.profile||g.profile||{},level=p.startingPoint||'';document.getElementById('generation-profile').innerHTML=`<h2>1. 设置当前研发学习起点</h2><form id="generation-profile-form" class="generation-form"><label for="generation-startingPoint">起点（请明确选择，不复用旧档案）</label><select id="generation-startingPoint" name="startingPoint" required><option value="">请选择</option>${[['beginner','零基础'],['intermediate','已有编程基础'],['advanced','已有Agent工程实践']].map(([v,l])=>`<option value="${v}" ${level===v?'selected':''}>${l}</option>`).join('')}</select>${generationField('goal','学习与产品目标',p.goal||'',true)}<button class="primary" type="submit">保存研发档案</button></form><p id="generation-profile-version">${g.profile?'已保存版本 '+generationEscape(g.profile.version):'尚未保存'}</p><p>e03先修：c02 / c03 / e02。先诊断“资料与请求的区别、文档ID与权限、轨迹与副作用”，缺证请补先修；预览不代表工程能力通过。任何起点均不能跳过先修。</p>`;
const s=g.drafts.submission||{};document.getElementById('generation-submission').innerHTML=`<h2>4. 提交作品自述证据</h2><form id="generation-submission-form" class="generation-form"><label for="generation-chapterId">关联章节（允许不关联）</label><select id="generation-chapterId" name="chapterId"><option value="">不关联</option>${g.chapters.map(c=>`<option value="${generationEscape(c.id)}" ${s.chapterId===c.id?'selected':''}>e03 · 版本 ${generationEscape(c.version)} · ${generationEscape(c.id)}</option>`).join('')}</select>${generationField('productTitle','作品标题',s.productTitle||'',true,'input')}${generationField('productVersion','作品版本',s.productVersion||'',true,'input')}${generationField('artifactUrl','作品链接（记录引用，不抓取）',s.artifactUrl||'',false,'input')}${generationField('runEvidence','运行证据引用（每行一条，允许缺证）',s.runEvidence||'')}${generationField('actualResult','实际结果（未知可如实记录）',s.actualResult||'')}<button class="primary" type="submit">保存作品证据新版本</button></form><p>服务不访问或执行链接；仅自述保存，缺证会标为不完整，不能获得验证通过。</p>`;generationRenderReviewForm();}
function generationRenderReviewForm(){const g=generationClient,el=document.getElementById('generation-review');if(!el||!g.user)return;const r=g.drafts.review||{};el.innerHTML=`<h2>5. 当次自评复盘</h2>${g.submissions.length?`<form id="generation-review-form" class="generation-form"><label for="generation-submissionId">本次作品提交</label><select id="generation-submissionId" name="submissionId" required>${g.submissions.map(s=>`<option value="${generationEscape(s.id)}" ${r.submissionId===s.id?'selected':''}>${generationEscape(s.productTitle)} · ${generationEscape(s.productVersion)} · ${generationEscape(s.id)}</option>`).join('')}</select>${[['goal','目标与评价标准'],['evidence','证据引用（每行一条）'],['result','实际结果'],['gap','差距'],['cause','原因假设或未知'],['owner','改进责任人'],['nextAction','下一步'],['retestMethod','复验方法'],['retestResult','复验结果']].map(([k,l])=>generationField(k,l,r[k]||'',['goal','result','gap','cause','owner','nextAction','retestMethod'].includes(k))).join('')}<button class="primary" type="submit">保存当次自评新记录</button></form>`:'<p>先保存一项作品证据，再关联当次复盘。</p>'}<p>类型固定“当次自评”。独立审核：未审核；人类专业审核：未审核。新作品版本不继承旧审核结论。</p>`;}
function generationRenderStatus(){const g=generationClient;if(!g.active||!g.user)return;const ready=g.health?.generation;document.getElementById('generation-config').innerHTML=`<p>${ready?.configured?'服务声明配置就绪；提交时服务仍会重新核对':'真实生成已阻止'}${ready?.missing?.length?'；缺项：'+generationEscape([...new Set(ready.missing.map(generationMissingLabel))].join('、')):''}</p><p>不在网页填写密钥。缺供应商、模型或预算时不会产生成功教材。</p>`;document.getElementById('generation-submit').disabled=!ready?.configured||!g.profile||g.busy;document.getElementById('generation-jobs').innerHTML=`<h3>已持久保存的任务</h3>${g.jobs.length?g.jobs.map(j=>`<article class="generation-job"><button class="text-link" data-generation="job" data-id="${generationEscape(j.id)}">${generationEscape(generationStatus[j.status]||j.status)} · ${generationEscape(j.id)}</button><p>${generationEscape(j.createdAt)} · 输入版本 ${generationEscape(generationText(j.versions))}</p>${j.retryOfJobId?`<p>重试关联：${generationEscape(j.retryOfJobId)}</p>`:''}${j.error?`<p>错误 ${generationEscape(generationText(j.error))}</p>`:''}${['queued','running'].includes(j.status)?`<button class="outline" data-generation="cancel" data-id="${generationEscape(j.id)}">取消任务</button>`:''}${['failed','cancelled'].includes(j.status)?`<button class="outline" data-generation="retry" data-id="${generationEscape(j.id)}">新建关联重试</button>`:''}${j.status==='succeeded'&&j.chapterId?`<button class="outline" data-generation="chapter" data-id="${generationEscape(j.chapterId)}">阅读已保存版本</button>`:''}</article>`).join(''):'<p>尚无任务。刷新后读取服务记录，不创建自动请求。</p>'}`;
document.getElementById('generation-chapters').innerHTML=g.chapters.length?g.chapters.map(c=>`<p><button class="text-link" data-generation="chapter" data-id="${generationEscape(c.id)}">e03草稿 · 固定版本 ${generationEscape(c.version)} · ${generationEscape(c.createdAt)}</button></p>`).join(''):'<p>暂无模型产物；作者初稿在下方独立阅读。</p>';document.getElementById('generation-history').innerHTML=`<h2>当前账户作品与自评历史</h2>${g.submissions.map(s=>`<details><summary>${generationEscape(s.productTitle)} · ${generationEscape(s.productVersion)} · ${s.evidenceStatus==='incomplete'?'证据不完整':'自述证据未核实'}</summary><p>提交ID ${generationEscape(s.id)}</p>${generationMarkdown(s)}</details>`).join('')}${g.reviews.map(r=>`<details><summary>当次自评 · ${generationEscape(r.createdAt)} · 未独立审核／未专业审核</summary>${generationMarkdown(r)}</details>`).join('')}${!g.submissions.length&&!g.reviews.length?'<p>尚无记录。每次修订会保存新记录，不能覆盖已提交历史。</p>':''}`;if(g.detail)generationRenderDetail();}
function generationRenderDetail(){const g=generationClient,d=g.detail,el=document.getElementById('generation-detail');if(!el||!d)return;el.innerHTML=`<details open><summary>任务详情 ${generationEscape(d.job?.id)}</summary><p>状态 ${generationEscape(generationStatus[d.job?.status]||d.job?.status)}</p><p>冻结输入摘要 ${generationEscape(d.job?.inputHash)}</p><p>冻结画像 ${generationEscape(generationText(d.job?.profileSnapshot))}</p><h4>实际事件（按服务顺序，无猜测百分比）</h4>${(d.events||[]).map(e=>`<p>${generationEscape(e.sequence)} · ${generationEscape(generationStage[e.type]||e.type)} · ${generationEscape(e.createdAt)} · ${generationEscape(generationText(e.data))}</p>`).join('')}<h4>实际尝试</h4>${(d.attempts||[]).map(a=>`<p>${generationEscape(a.id)} · ${generationEscape(a.status)} · ${generationEscape(generationText(a.error||''))} · 供应商执行结果：${a.providerOutcomeUnknown?'未知':'以服务证据为准'}</p>`).join('')}<p>取消会隔离本地提交；外部供应商是否实际停止可能未知，不能保证远端恰好一次。</p></details>`;}
function generationRenderChapter(chapter){const g=generationClient,c=chapter,r=c.result||{},draft=r.chapterDraft||r;const el=document.getElementById('generation-chapter');if(!el)return;const sections=draft.sections||[],simulation=r.checks?.simulation===true||r.provenance?.simulation===true||r.provenance?.provider==='simulation';el.innerHTML=`<article class="generation-draft"><h3>${generationEscape(draft.title||'e03模型草稿')} · 版本 ${generationEscape(c.version)}</h3>${simulation?'<div class="info-banner">测试模拟产物：不属于真实模型生成证据，不提供能力认证。</div>':''}<p>${simulation?'测试模拟草稿':'模型产物草稿'} · 章节ID ${generationEscape(c.id)} · 作业 ${generationEscape(c.jobId)} · 尝试 ${generationEscape(c.attemptId)}</p><p>输入课程版本 ${generationEscape(generationText(g.jobs.find(j=>j.id===c.jobId)?.versions||'请读取关联任务'))} · 输出摘要 ${generationEscape(c.outputHash)}</p><p>先修：${generationEscape((g.curriculum?.prerequisites||['c02','c03','e02']).join('、'))}。新稿不继承作者审校。</p><div class="info-banner">独立内容审校：未审核 · 示例执行：未运行 · 人类专业审核：未审核 · 学习效果：未验证。引用关联或结构检查不能证明内容正确。</div>${sections.length?sections.map((s,i)=>`<section><h3>${i+1}. ${generationEscape(s.title||s.id)}</h3>${generationMarkdown(s.bodyMarkdown||s.content||s.body||'正文缺失')}<p>引用主张 ${generationEscape(generationText(s.claimIds||s.sourceIds||[]))}</p></section>`).join(''):generationMarkdown(draft)}<h4>来源与位置（受控输入，不声称动态检索）</h4>${(g.curriculum?.allowedSources||[]).map(generationSourceHTML).join('')}<details><summary>服务返回的关联检查与来源记录（未独立核实）</summary>${generationMarkdown({claims:r.claims,examples:r.examples,checks:r.checks,provenance:r.provenance,usage:r.usage,timings:r.timings,reviewStatus:c.reviewStatus})}</details></article>`;}
async function generationRefresh(renderForms=false){const g=generationClient,epoch=g.epoch;const results=await Promise.all(['/api/profile','/api/generation-jobs','/api/chapters','/api/submissions','/api/reviews'].map(p=>generationApi(p,'GET',undefined,epoch)));if(!g.active||epoch!==g.epoch)return;[g.profile,g.jobs,g.chapters,g.submissions,g.reviews]=[results[0].profile,results[1].jobs||[],results[2].chapters||[],results[3].submissions||[],results[4].reviews||[]];if(renderForms)generationRenderForms();generationRenderStatus();if(g.selectedJob){g.detail=await generationApi('/api/generation-jobs/'+encodeURIComponent(g.selectedJob),'GET',undefined,epoch);if(g.active&&epoch===g.epoch)generationRenderDetail();}}
function generationPoll(){const g=generationClient;clearTimeout(g.timer);if(!g.active||!g.user)return;g.timer=setTimeout(async()=>{try{await generationRefresh(false);}catch(e){if(e.name!=='AbortError')generationNotify(generationUserError(e),true);}generationPoll();},3000);}
function generationReadForm(form){return Object.fromEntries(new FormData(form));}
function generationLines(v){return String(v||'').split(/\r?\n/).map(v=>v.trim()).filter(Boolean);}
function generationKey(){return typeof crypto!=='undefined'&&typeof crypto.randomUUID==='function'?crypto.randomUUID():'request-'+Date.now()+'-'+Math.random().toString(36).slice(2);}
async function generationAction(button){const g=generationClient,action=button.dataset.generation;if(action==='auth-switch'){g.authMode=g.authMode==='login'?'register':'login';generationRenderAccount();return;}if(action==='reconnect'){generationUnmount();await generationMount();return;}if(g.busy)return;g.busy=true;button.disabled=true;try{if(action==='logout'){// clear immediately; use old CSRF for server logout before disposal
const token=g.csrfToken;generationClearPrivate();generationRenderAccount();await fetch('/api/auth/logout',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':token||''},body:'{}',credentials:'same-origin'}).then(r=>{if(!r.ok)throw new Error('退出请求未确认；本地界面已清空，请重试或关闭当前服务');});generationNotify('已退出；私有缓存及未提交输入已清空。');return;}
if(action==='generate'){if(!g.profile||!g.health?.generation?.configured)throw new Error('请先保存画像并配置供应商、模型与预算');const key=g.drafts.jobKey||generationKey();g.drafts.jobKey=key;const data=await generationApi('/api/generation-jobs','POST',{moduleId:'e03',profileVersion:g.profile.version,idempotencyKey:key});delete g.drafts.jobKey;g.selectedJob=data.job.id;generationNotify('任务已由服务接收；等待真实结果。');await generationRefresh(false);}
if(action==='cancel'){await generationApi('/api/generation-jobs/'+encodeURIComponent(button.dataset.id)+'/cancel','POST',{});generationNotify('本地取消已保存；外部调用停止结果可能未知。');await generationRefresh(false);}
if(action==='retry'){const id=button.dataset.id,key=g.drafts['retry-'+id]||generationKey();g.drafts['retry-'+id]=key;const data=await generationApi('/api/generation-jobs/'+encodeURIComponent(id)+'/retry','POST',{idempotencyKey:key});delete g.drafts['retry-'+id];g.selectedJob=data.job.id;generationNotify('已保存关联重试；旧任务和版本保留。');await generationRefresh(false);}
if(action==='job'){g.selectedJob=button.dataset.id;g.detail=await generationApi('/api/generation-jobs/'+encodeURIComponent(g.selectedJob));generationRenderDetail();}
if(action==='chapter'){const data=await generationApi('/api/chapters/'+encodeURIComponent(button.dataset.id));g.chapter=data.chapter;g.selectedChapter=data.chapter.id;generationRenderChapter(data.chapter);}
if(action==='export'){const data=await generationApi('/api/export');const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='职造-当前研发账户.json';a.click();URL.revokeObjectURL(url);generationNotify('已导出当前账户数据；不包含密码或供应商密钥。');}}
catch(e){if(e.name!=='AbortError')generationNotify(generationUserError(e),true);}finally{g.busy=false;if(button.isConnected)button.disabled=false;generationRenderStatus();}}
document.addEventListener('click',e=>{const button=e.target.closest?.('button[data-generation]');if(button)generationAction(button);});
document.addEventListener('input',e=>{const form=e.target.closest?.('.generation-form');if(!form||form.id==='generation-auth-form')return;const key={'generation-profile-form':'profile','generation-submission-form':'submission','generation-review-form':'review'}[form.id];if(key){generationClient.drafts[key]=generationReadForm(form);generationClient.dirty=true;}});
document.addEventListener('change',e=>{const form=e.target.closest?.('.generation-form');if(!form||form.id==='generation-auth-form')return;const key={'generation-profile-form':'profile','generation-submission-form':'submission','generation-review-form':'review'}[form.id];if(key){generationClient.drafts[key]=generationReadForm(form);generationClient.dirty=true;}});
document.addEventListener('submit',async e=>{const form=e.target;if(!/^generation-(auth|profile|submission|review)-form$/.test(form.id))return;e.preventDefault();const g=generationClient;if(g.busy)return;const values=generationReadForm(form),button=form.querySelector('button[type="submit"]');g.busy=true;if(button)button.disabled=true;const epoch=g.epoch;try{if(form.id==='generation-auth-form'){const data=await generationApi('/api/auth/'+g.authMode,'POST',values,epoch);generationClearPrivate();g.controller=new AbortController();g.user=data.user;g.csrfToken=data.csrfToken;form.reset();generationRenderAccount();await generationRefresh(true);generationPoll();generationNotify('本地研发身份已确认，请明确选择学习起点。');}
if(form.id==='generation-profile-form'){await generationApi('/api/profile','PUT',{startingPoint:values.startingPoint,goal:values.goal},epoch);delete g.drafts.profile;await generationRefresh(false);document.getElementById('generation-profile-version').textContent='已保存版本 '+g.profile.version;generationNotify('研发档案已由服务保存。');}
if(form.id==='generation-submission-form'){const data=await generationApi('/api/submissions','POST',{...values,moduleId:'e03',chapterId:values.chapterId||null,runEvidence:generationLines(values.runEvidence)},epoch);delete g.drafts.submission;await generationRefresh(false);form.reset();g.drafts.review={...(g.drafts.review||{}),submissionId:data.submission.id};generationRenderReviewForm();generationNotify(data.submission.evidenceStatus==='incomplete'?'自述证据已保存，但证据不完整。':'自述证据已保存，尚未验证。');}
if(form.id==='generation-review-form'){await generationApi('/api/reviews','POST',{...values,evidence:generationLines(values.evidence)},epoch);delete g.drafts.review;await generationRefresh(false);generationRenderReviewForm();generationNotify('当次自评已保存；独立与专业状态仍为未审核。');}g.dirty=['profile','submission','review'].some(k=>Boolean(g.drafts[k]));}
catch(err){if(err.name!=='AbortError')generationNotify(generationUserError(err),true);}finally{g.busy=false;if(button?.isConnected)button.disabled=false;generationRenderStatus();}});
